cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db', { readonly: true });

// Check if there are variants for the mouse product in rt_variants or any other product with 'mouse' in name
const mouseProducts = db.prepare(\"SELECT product_id, name, variants_json, source_skill FROM products WHERE name LIKE '%Mouse%' OR name LIKE '%mouse%'\").all();
console.log('=== ALL MOUSE PRODUCTS ===');
mouseProducts.forEach(p => console.log(JSON.stringify(p, null, 2)));

// Check rt_variants for any mouse product
for (const p of mouseProducts) {
  const vars = db.prepare('SELECT * FROM rt_variants WHERE product_id = ?').all(p.product_id);
  if (vars.length > 0) {
    console.log('\\nVariants for', p.product_id, ':', JSON.stringify(vars, null, 2));
  } else {
    console.log('\\nNo rt_variants for', p.product_id);
  }
}

// Check compatible products for the mouse
console.log('\\n=== COMPATIBLE PRODUCTS FOR MOUSE (PROD-FA0948) ===');
const compatIds = ['PROD-B98D14','PROD-2DBA15','PROD-7C0240','PROD-73FAB4'];
for (const cid of compatIds) {
  const cp = db.prepare('SELECT product_id, name, category FROM products WHERE product_id = ?').get(cid);
  if (cp) console.log(cid, '->', cp.name, '(' + cp.category + ')');
}
"
